const appointment = $('Buscar Agendamento').item.json[0] || $('Buscar Agendamento').item.json;
const tenant = appointment?.tenants;
if (!appointment || !tenant) throw new Error('Agendamento ou tenant não encontrado');
if (!tenant.google_calendar_id || !tenant.google_refresh_token) return [{ json: { ok: false, error: 'Google Calendar não configurado para este tenant' } }];
if (!appointment.google_calendar_event_id) return [{ json: { ok: false, error: 'Appointment não possui evento no Google Calendar' } }];

const body = new URLSearchParams({
  grant_type: 'refresh_token',
  refresh_token: tenant.google_refresh_token,
  client_id: process.env.GOOGLE_CLIENT_ID,
  client_secret: process.env.GOOGLE_CLIENT_SECRET,
}).toString();
const tokenRes = await fetch('https://oauth2.googleapis.com/token', {
  method: 'POST',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body,
});
const tokenData = await tokenRes.json();
if (!tokenData.access_token) throw new Error('Falha ao atualizar token do Google Calendar');

const eventRes = await fetch(`https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(tenant.google_calendar_id)}/events/${encodeURIComponent(appointment.google_calendar_event_id)}`, {
  method: 'DELETE',
  headers: {
    Authorization: `Bearer ${tokenData.access_token}`,
  },
});
if (!eventRes.ok) {
  const errorData = await eventRes.json().catch(() => ({}));
  throw new Error(`Google Calendar delete failed: ${errorData.error?.message || eventRes.statusText}`);
}

return [{ json: { ok: true } }];
